/* Hint cards: the shell: header, account figures, workspaces, account menu, Help, Replay launcher, sonification popup (front 16.11.2026).
   Registered on the hint engine (hints-engine.js); the look is the one of hints-brief.js. Every card is built from the element and its live values.
   Sources read for the rules quoted in the cards: panels.js renderAccount, core/account.js (summary, stop-out at 50, execFill, JUR caps), trade.js (MARGIN_TEXT),
   persist.js (KIND), livefeed.js (pill), obs.js (sonification), replay.js (launcher), app.js (shortcuts), ui.js (account menu, Display settings).
   Verify with: node tools/hint-audit.mjs trade menu-account pop-sonification dlg-help dlg-replay (0 elements without a card, 0 generic cards). */
(() => {
  const { add, tip, card, plain, sec, scale, tbl, p, esc, nm, sgn, cls, lbl } = HX;
  const g = f => { try { return f(); } catch (e) { return null; } };
  const acct = () => g(() => account());
  const usd = (v, s) => g(() => usdFmt(v, s)) || String(v);
  const txt = (el, sel) => { const e = sel ? el.querySelector(sel) : el; return e ? lbl(e) : ''; };
  const nOpen = () => g(() => S.positions.length) || 0;
  const peakOf = a => Math.max(g(() => S.peak) || g(() => INIT_BAL) || 100000, a ? a.eq : 0);
  const stale = () => document.body.classList.contains('pnl-stale');
  const STALE = 'These figures are as last seen: the price feed or the server link is down, so they are not moving.';
  const kind = () => g(() => acctKind()) || null;
  const live = () => !!g(() => TradeLink.live);
  const sig = (v, d = 2) => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v).toFixed(d);
  const on = b => b ? 'on' : 'off';
  const C = (title, chip, tone, plainT, o = {}) => card({ title, chip, tone, plain: plainT, value: o.value, vlabel: o.vlabel, vcls: o.vcls, sub: o.sub, secs: o.secs, watch: o.watch, eg: o.eg, use: o.use });
  const VAR = (h, pre) => h && h.replace(/<small>/, '<small>' + pre + ' · ');
  const addE = (sel, f, o) => add(sel, f, { ...(o || {}), empty: true });
  const T = rows => tbl(rows.map(r => Array.isArray(r) ? { c: r } : r));

  /* ------------------------------------------------------------------ workspaces (header, #views) */
  const WS = {
    trade: ['Trade', 'Alt+1', 'The working screen: the watchlist on the left, the chart in the middle, the order ticket on the right and, under the chart, the dock with Positions, Orders, History, Alerts and the Journal.',
      [['Watchlist', 'every instrument, with live bid and ask'], ['Chart', 'candles, indicators, drawings, layouts'], ['Ticket', 'size by lots, risk % or risk $, stop, target, margin, risk and R:R before you send'], ['Dock', 'positions, pending orders, closed trades, price alerts']],
      'Stay here to trade. Open the other workspaces to prepare or to review.'],
    monitor: ['Monitor', 'Alt+2', 'A dense board of quotes: every instrument on one screen, to scan prices and moves without a chart.',
      [['Quotes', 'bid, ask, change and spread per instrument'], ['Use', 'scan first, then click an instrument to trade it']], 'Use it to find what moves, then go back to Trade.'],
    research: ['Research', 'Alt+3', 'The analysis tools: the Market Brief, the Observatory, Correlation, Volatility and the economic Calendar.',
      [['Market Brief', 'trend score, key levels, a plan template per pair'], ['Observatory', 'correlation map, regimes, recurrence, drivers, baskets'], ['Correlation, Volatility', 'how pairs move together and how much'], ['Calendar', 'scheduled releases']], 'Read before you trade: a level and an event time are worth more than a hunch.'],
    lab: ['Strategy Lab', 'Alt+4', 'Where you test ideas on past prices: the Backtester, the Risk Lab (Monte Carlo on your own journal) and the Calculators.',
      [['Backtester', 'a rule run on the platform’s own prices'], ['Risk Lab', '1,000 Monte Carlo paths from your journal stats'], ['Calculators', 'size, pip value, margin']], 'Test a rule here before it meets your account. A good test is evidence, not a promise.'],
    coach: ['Coach', 'Alt+5', 'Your behaviour in numbers: the Behaviour pages, the Challenge and the Journal analytics built from your closed trades.',
      [['Behaviour', 'pre-mortem, skipped trades, disposition effect'], ['Challenge', 'progress against a set of trading rules'], ['Journal', 'win rate, expectancy, drawdown, by pair, session and side']], 'Open it after a session: it reads what you did, not what you meant to do.']
  };
  add('#views > button', el => {
    const k = el.dataset.view, w = WS[k]; if (!w) return null; const here = el.classList.contains('on') || el.getAttribute('aria-current') === 'page';
    const n = nOpen(), o = g(() => S.orders.length) || 0, al = g(() => S.alerts.filter(a => !a.done).length) || 0, ni = g(() => Engine.INSTR.length);
    const live1 = k === 'trade' ? `${n} open position${n === 1 ? '' : 's'} · ${o} pending order${o === 1 ? '' : 's'} · ${al} active alert${al === 1 ? '' : 's'}` : k === 'monitor' && ni ? `${ni} instruments on the board` : '';
    return C(w[0], here ? 'you are here' : 'opens this workspace', '', w[2], { value: esc(w[1]), vlabel: 'Keyboard shortcut', sub: live1 || (here ? 'open now' : ''),
      secs: [sec('What is in it', T(w[3]))], use: w[4] });
  });

  /* ------------------------------------------------------------------ the brand */
  add('.topbar .wordmark', () => {
    const b = g(() => (document.getElementById('buildTag') || {}).textContent) || '';
    return C('tradeBerry', 'a terminal for trading and for learning to trade well', '', 'The name of the app. Prices come from the broker platform; the account, the tools and the cards are tradeBerry’s own. Every figure on screen can be explained: turn Hints on and point at it.',
      { value: esc(b.replace(/^tradeBerry\s*/, '') || 'dev'), vlabel: 'Version and build', sub: esc(g(() => kind().title) || ''), use: 'Quote the build when you report something: it says exactly which code is running.' });
  });

  add('.topbar .wordmark .wm-t, .topbar .wordmark .wm-b', el => C(lbl(el) === 'trade' ? 'trade' : '.Berry', 'half of the name', '', lbl(el) === 'trade' ? 'The first half of the name: the verb. The terminal exists to trade, and to learn to trade well.' : 'The second half of the name. The four bars of the logo rise from left to right.', { use: 'The whole name, with the build, is on the card of the logo.' }));

  /* ------------------------------------------------------------------ the account figures */
  const figCard = el => {
    const b = el.querySelector('b'); if (!b) return null; const a = acct(); if (!a) return null; const id = b.id, dd = (peakOf(a) - a.eq) / peakOf(a) * 100, n = nOpen(), st = stale() ? STALE : '';
    if (id === 'mBal') return C('Balance', 'closed results, less the commission paid', '', `The cash of the account: the starting <b>${usd(g(() => INIT_BAL) || 100000)}</b> plus every closed result, less the commission of the trades opened. The floating result of an open trade does not change it until the trade closes, but its <b>round-turn commission</b> leaves the balance the moment the trade opens (core/account.js).${st ? ' ' + esc(st) : ''}`,
      { value: usd(a.balance), vlabel: 'Balance', sub: n ? `${n} open · floating ${usd(a.fl, true)}` : 'no open trades',
        secs: [sec('Balance and equity', T([['Balance', usd(a.balance)], ['+ Floating P&L', usd(a.fl, true)], { c: ['= Equity', usd(a.eq)], on: true }]) + p('The gap between the two is money that is still open: it can go either way before it is booked.'))],
        watch: 'The balance hides open losses. A flat balance with a large floating loss is a bad account.', use: 'Judge the account by Equity; use Balance to see what was actually banked.' });
    if (id === 'mEq') return C('Equity', dd < .05 ? 'at its peak' : dd < 5 ? `${dd.toFixed(1)}% under its peak` : dd < 10 ? `${dd.toFixed(1)}% under its peak` : `${dd.toFixed(1)}% under its peak: a deep drawdown`, dd < 5 ? 'ok' : dd < 10 ? 'warn' : 'bad',
      `What the account is worth <b>right now</b> if every open trade closed at the current price: balance plus floating P&L. It is the figure margin is measured against.${st ? ' ' + esc(st) : ''}`,
      { value: usd(a.eq), vlabel: 'Equity', sub: `peak ${usd(peakOf(a))}`,
        secs: [sec('Against its peak', scale([{ w: 5, label: 'under 5%', tone: 'ok' }, { w: 5, label: '5 to 10%', tone: 'warn' }, { w: 10, label: 'over 10%', tone: 'bad' }], 0, 20, Math.min(20, Math.max(0, dd)), v => v.toFixed(0) + '%')
          + p('A rule of thumb used by this card only, not a rule of the platform: under 5% below the highest equity seen is calm, 5 to 10% needs attention, over 10% is a deep drawdown. The platform itself sets no drawdown threshold here.'))],
        watch: 'Equity moves with every tick while a trade is open: it is the figure that triggers a margin call, not the balance.', use: 'If equity is falling and the stop is not set, decide now what loss you accept, before the market decides.' });
    if (id === 'mPnl') { const k = g(() => S.positions.map(x => posPnl(x).pnl)) || [], w = k.filter(x => x > 0).length, l = k.filter(x => x < 0).length;
      return C('Floating P&L', !n ? 'nothing open' : a.fl > 0 ? 'open trades are in profit' : a.fl < 0 ? 'open trades are at a loss' : 'open trades at break-even', !n ? '' : a.fl > 0 ? 'ok' : a.fl < 0 ? 'bad' : '',
        `The result of the open trades if they closed now: price move plus the swap booked so far. Longs are valued at the <b>bid</b>, shorts at the <b>ask</b>, so the spread is already in it.${st ? ' ' + esc(st) : ''}`,
        { value: usd(a.fl, true), vcls: cls(a.fl), vlabel: 'Floating P&L', sub: n ? `${w} in profit · ${l} at a loss · ${n - w - l} flat` : 'no open positions',
          secs: [sec('Where it goes', p('When a trade closes its result moves from here into the Balance. Until then it is a number, not money.'))],
          watch: 'A floating profit is not yours until you close it, and a floating loss is not final until you do.', use: 'Look at it next to the Margin level: a small P&L with a low level means a big position.' }); }
    if (id === 'mFree') { const fr = a.eq > 0 ? a.free / a.eq : 0; return C('Free margin', a.free < 0 ? 'negative: no room for a new trade' : !n ? 'all equity is free' : fr < .25 ? `only ${(fr * 100).toFixed(0)}% of equity is free` : `${(fr * 100).toFixed(0)}% of equity is free`, a.free < 0 ? 'bad' : !n ? '' : fr < .25 ? 'warn' : 'ok',
      `Equity minus the margin already used: what is left to open <b>new</b> trades. A new order is refused when its initial margin is more than this. Rule used here for the colour: under 25% of equity free is a warning.${st ? ' ' + esc(st) : ''}`,
      { value: usd(a.free), vcls: a.free < 0 ? 'dn' : '', vlabel: 'Free margin', sub: `used ${usd(a.mg)} of equity ${usd(a.eq)}`,
        secs: [sec('How it is made', T([['Equity', usd(a.eq)], ['− Used margin', usd(a.mg)], { c: ['= Free margin', usd(a.free)], on: true }]))],
        watch: 'Free margin is not a risk budget: using all of it leaves the account one move from a margin call.', use: 'Size the next trade by what you accept to lose on it, then check it fits in the free margin, not the other way round.' }); }
    if (id === 'mLevel') { const lv = a.level, fin = isFinite(lv), tone = !fin ? '' : lv < 100 ? 'bad' : lv < 150 ? 'warn' : 'ok';
      return C(lv < 100 && fin ? 'Stop-out at 50%' : 'Margin level', !fin ? 'no open positions: no margin in use' : lv < 50 ? 'below the stop-out line' : lv < 100 ? 'no new positions can open' : lv < 150 ? 'low: little room before trouble' : 'comfortable', tone,
        `Equity divided by the used margin, times 100. It says how many times your equity covers the margin the open trades hold. Under <b>100%</b> no new position can open; at <b>50%</b> the broker closes positions, the worst first (stop-out).${st ? ' ' + esc(st) : ''}`,
        { value: fin ? nf0.format(lv) + '%' : '—', vcls: fin && lv < 150 ? 'dn' : '', vlabel: 'Margin level', sub: fin ? `equity ${usd(a.eq)} ÷ used margin ${usd(a.mg)}` : 'no margin used',
          secs: [fin ? sec('Where it sits', scale([{ w: 50, label: 'stop-out', tone: 'bad' }, { w: 50, label: 'no new trades', tone: 'bad' }, { w: 50, label: 'low', tone: 'warn' }, { w: 250, label: 'comfortable', tone: 'ok' }], 0, 400, Math.min(400, Math.max(0, lv)), v => Math.round(v) + '%')) : '',
            sec('The rule in the code', T([['under 150%', 'the figure turns red'], ['under 100%', 'no new position; the label says Stop-out at 50%'], ['at 50%', 'positions are closed, worst first, until the level is back above it']]))],
          watch: 'The level falls fast when the price moves against a large position: at 100:1 leverage a few percent of price can take it from comfortable to stop-out.', use: 'Keep it well above 150% by sizing small; do not wait for the red to act.' }); }
    if (id === 'mMargin') { const rows = (g(() => S.positions.slice(0, 5).map(x => [`${pretty(x.sym)} ${x.side === 'buy' ? 'long' : 'short'} ${x.lots.toFixed(2)}`, usd(x.im)])) || []);
      return C('Used margin', n ? `${n} position${n === 1 ? '' : 's'} hold margin` : 'nothing held', '', `The deposit the open positions hold. It is fixed when a position opens (notional at the fill ÷ leverage), scaled when part of it closes, and <b>does not follow the price</b>. A leverage or jurisdiction change rescales it.`,
        { value: usd(a.mg), vlabel: 'Used margin', sub: `margin level ${isFinite(a.level) ? nf0.format(a.level) + '%' : '—'}`, secs: rows.length ? [sec('Largest holders', T(rows))] : [],
          use: 'Compare it with the equity: the share of equity that is tied up is your real exposure.' }); }
    if (id === 'mDD') return C('Drawdown', dd < .01 ? 'at the peak' : dd < 5 ? 'a small step down' : dd < 10 ? 'a real drawdown' : 'a deep drawdown', dd < 5 ? 'ok' : dd < 10 ? 'warn' : 'bad',
      `How far equity is under the highest equity seen in this account, in percent: <b>(peak − equity) ÷ peak</b>. It is measured on equity, so an open loss counts before it is closed.`,
      { value: pct(-dd, 2), vcls: dd > .01 ? 'dn' : '', vlabel: 'Drawdown now', sub: `peak ${usd(peakOf(a))} · equity ${usd(a.eq)}`,
        secs: [sec('Why it matters', T([['10% down', 'needs +11.1% to get back'], ['20% down', 'needs +25% to get back'], ['50% down', 'needs +100% to get back']]) + p('Losses are harder to recover than they were to make: that is why the first job is to keep the drawdown small.'))],
        use: 'A common habit (a rule of thumb, not a platform rule): when a drawdown gets deep, trade smaller until equity recovers.' });
    return null;
  };
  add('#acct .m', figCard, { control: true }); // inside the account bar (a button on the phone): the click is kept, the card shows on hover
  add('#acctPop .m', figCard);
  add('#acct', () => {
    const a = acct(); if (!a) return null; return C('Account bar', 'the five numbers that tell you where you stand', stale() ? 'warn' : '', `Balance, Equity, Floating P&L, Free margin and Margin level, live. Point at one for its own explanation. On narrower screens the rest (used margin, drawdown, leverage) sit behind the arrow next to it.${stale() ? ' ' + esc(STALE) : ''}`,
      { value: usd(a.eq), vlabel: 'Equity', sub: `margin level ${isFinite(a.level) ? nf0.format(a.level) + '%' : '—'}`,
        secs: [sec('Read them in this order', T([['1 Margin level', 'can I be forced out?'], ['2 Free margin', 'can I open more?'], ['3 Equity vs Balance', 'how much is open risk?']]))], use: 'Look at the bar before every trade, not after.' });
  });
  add('#acct .rp-acct', () => C('Replay account', 'a separate account', '', 'In Market replay the account is a fresh account of its own. Your main account is frozen and untouched while Replay is open.', { use: 'Close the replay to come back to your main account.' }));
  add('#acctMore', () => C('More account figures', 'used margin, drawdown, leverage', '', 'On a narrow screen the bar shows only the main figures. This arrow opens the rest: used margin, drawdown and the leverage choice.', { use: 'Open it before sizing a trade.' }));
  add('#levSel', el => {
    const sym = g(() => S.set.sym) || 'EURUSD', lots = 1, nt = g(() => notionalUsd(sym, lots)), lev = g(() => effLev(sym)), j = g(() => jurOf(S.set)), choice = g(() => S.set.lev);
    return C('Leverage', choice > 0 ? `1:${choice} where the sheet allows` : 'the instrument sheet default', '', `The ratio between the size of a position and the margin it holds. <b>${choice > 0 ? '1:' + choice : 'The sheet default'}</b> is your choice; it never goes above the instrument’s maximum nor above the jurisdiction cap${j && !j.none ? ' (' + esc(j.name) + ')' : ''}.`,
      { value: lev ? '1:' + lev : '—', vlabel: `Effective on ${esc(pretty(sym))}`, sub: nt && lev ? `1 lot = ${usd(nt)} notional, ${usd(nt / lev)} margin` : '',
        secs: [sec('What changes', p('A change recomputes the used margin of open positions. With open trades it first shows the new margin and level, and asks before it applies.'))],
        watch: 'More leverage does not add edge: it makes each tick worth more and the stop-out closer.', use: 'Pick the leverage you can survive, not the one that lets you open the most.' });
  });
  add('#acctPop label.sel > span', () => C('Leverage', 'the choice sits in the select next to it', '', 'The label of the leverage select. The select sets the ratio of position size to margin; the instrument sheet and the jurisdiction cap can only lower it.', { use: 'Change it before you open trades, not with positions on.' }));
  add('#demoPill', el => { const k = kind(); return C(lbl(el) || 'Account type', 'what kind of account this is', k && k.key === 'live' ? 'warn' : '', esc(g(() => k.title) || 'The account type, as the account menu says it.'), { use: 'Read it before you trade: real money or none changes how much care a click needs.' }); }, { empty: true });
  add('#persistPill', el => C(lbl(el) || 'Storage', 'where the account is saved', /unsaved|Read-only/.test(lbl(el)) ? 'warn' : '', esc(el.title || 'How this browser saves the account.'), { use: 'Export the account now and then: it is the only copy you keep yourself.' }));
  add('#chalPill', el => C(lbl(el) || 'Challenge', 'progress of your trading challenge', '', 'The state of the Challenge you are running. Click it to open the Coach page with the rules and the progress.', { use: 'Check it after each trade: a challenge is lost on a rule, not on a feeling.' }), { empty: true });

  /* ------------------------------------------------------------------ the price source pill */
  add('#feedPill', el => {
    const t = lbl(el), down = el.classList.contains('feed-down'), liveOn = el.classList.contains('feed-live'), rp = /^REPLAY/.test(t), k = kind(), lf = g(() => LiveFeed) || {};
    const tone = down ? 'bad' : liveOn ? 'ok' : 'warn';
    const chip = rp ? 'a replay is running, not the live market' : down ? 'no prices: trading is paused' : liveOn ? 'real prices from the broker platform' : 'no live prices reach the terminal';
    const pl = rp ? 'A <b>Market replay</b> is running: the prices are replayed, not the live market. Your main account is frozen until the replay is closed.'
      : down ? 'The broker platform has not answered for over <b>10 seconds</b>. Prices are frozen and every instrument is closed until it answers again; an order sent now would use a price that is no longer the market.'
        : liveOn ? `The bid and ask on screen are the broker platform’s real prices, ${lf.streaming ? 'streamed as they change' : 'refreshed every second'} through the tradeBerry server.`
          : 'No live prices from the broker platform reach this terminal. The prices on screen are not the platform’s.';
    return C('Price source', chip, tone, pl, { value: esc(t), vlabel: 'Status now', sub: k ? esc(k.title) : '',
      secs: [sec('The states', T([{ c: ['LIVE · platform prices', 'real bid and ask'], on: liveOn }, { c: ['NO FEED', 'platform silent over 10 s: frozen, trading paused'], on: down }, { c: ['OFFLINE', 'no live prices reach the terminal'], on: !liveOn && !down && !rp }, { c: ['REPLAY', 'replayed prices, main account frozen'], on: rp }]))],
      watch: down ? 'Do not read a frozen price as the market: it is the last one seen.' : '', use: 'Glance at it before any order: a trade is only as good as the price it is based on.' });
  });

  /* ------------------------------------------------------------------ icon buttons */
  add('#cmdBtn', () => C('Command bar', 'type an order or jump to any tool', '', 'A single line that understands orders and navigation: <b>buy 1 eurusd sl 20 tp 40</b>, <b>close losers</b>, <b>alert usdjpy above 159</b>, <b>tf 1h</b>, <b>brief gbpjpy</b>, <b>backtest audusd</b>. Typing two letters quickly anywhere opens it too.',
    { value: '⌘K', vlabel: 'Shortcut (Ctrl+K on Windows)', secs: [sec('How an order goes', T([['1', 'Enter shows what the command will do'], ['2', 'a trade, an order or a mass close runs on the <b>second</b> Enter'], ['3', 'a blocked order never runs; the reason is shown']]))],
      watch: 'The bar can send real orders. Read the line it shows before the second Enter.', use: 'Use it for what you do often: sizing from risk (“sell gbpjpy risk 1 sl 30 tp 60”) is faster here than in the ticket.' }));
  addE('#sonBtn', () => { const s = g(() => SON.on); const sym = g(() => pretty(S.set.sym)) || ''; return C('Listen to the market', s ? 'sound is on' : 'sound is off', '', `Turns price movement into sound, so you can follow the market without looking. A rising two-note chime is an uptick on <b>${esc(sym)}</b>, a falling one a downtick; the register follows the distance from the price 24 hours ago. A low pulse tracks your open P&L.`,
    { value: s ? 'On' : 'Off', vlabel: 'Sonification', sub: 'Shift+click or the arrow next to it opens the settings', use: 'Switch it on while you work on something else; it tells you when the pair you trade is moving.', watch: 'A sound is a cue, not a signal: it says the price moved, not that you should trade.' }); });
  add('#sonMore', () => C('Sound settings', 'opens the sonification popup', '', 'Opens the panel where you choose the price ticks, the portfolio heartbeat, the volume and the sensitivity. The popup closes when you click anywhere else.', { use: 'Lower the sensitivity if the ticks come too often.' }));
  addE('#soundBtn', () => { const s = g(() => S.set.sound); return C('Sounds', s ? 'sounds are on' : 'sounds are muted', '', 'Switches the app’s own alert sounds: a short beep when an order fills, a trade closes in profit or in loss, an alert fires, an order is refused or a news release arrives. It does not touch the market sound (the ear button).',
    { value: s ? 'On' : 'Off', vlabel: 'Alert sounds', secs: [sec('The beeps', T([['fill', 'rising two tones'], ['win / loss', 'high pair / falling pair'], ['alert', 'three tones'], ['error', 'one low tone'], ['news', 'two equal tones']]))], use: 'Keep them on while you trade: a refused order you did not hear is an order you think is working.' }); });
  addE('#themeBtn', () => { const t = g(() => S.set.theme) || 'dark'; return C('Light or dark', `${t} theme now`, '', `Switches the whole app between the dark and the light look. Prices, charts and colours follow. It is a preference of this browser, saved with your settings.`, { value: t === 'dark' ? 'Dark' : 'Light', vlabel: 'Theme', use: 'Dark rests the eyes on long sessions; light reads better in a bright room.' }); });
  addE('#rpBtn', () => C('Market replay', 'practice on a market you can rewind', '', 'Opens the replay launcher: pick a seed and a start, or your own recorded session, and play it forward bar by bar. The future is not computed until you reach it. Your main account is frozen while the replay is open and nothing in it touches it.',
    { secs: [sec('Two ways', T([['Seed replay', 'a generated market from a seed: the same seed and start give the same market'], ['Your session', 'your own recorded 1-minute prices, replayed']]))], use: 'Rehearse a setup ten times in the time one live trade takes, and judge it on all ten.' }));
  addE('#fsBtn', () => C('Full screen', 'uses the whole display', '', 'Hides the browser’s own bars so the terminal gets the entire screen. Press it again, or Esc, to leave.', { value: 'Shift+F', vlabel: 'Shortcut', use: 'Use it when the chart and the dock need every pixel.' }));
  add('#installBtn', () => C('Install app', 'run tradeBerry as an app', '', 'Installs tradeBerry as an app on this device: its own window, an icon, a faster start. It is the same page, not a different version, and your account stays where it is.', { use: 'Install it if you use it daily; the browser asks you to confirm.' }), { empty: true });
  add('#helpBtn', () => C('Shortcuts and guide', 'the quick guide', '', 'Opens the quick guide: keyboard shortcuts, what the app offers, the settings (one-click trading, jurisdiction, execution, display), and the export and import of the account. The same page opens with the question mark key.', { value: '?', vlabel: 'Key', use: 'Open it when you wonder how something is set.' }), { empty: true });
  addE('#userBtn', el => { const k = kind(), nm0 = g(() => document.getElementById('userName').textContent) || 'Local account', st = g(() => document.getElementById('userSt').textContent) || '';
    return C('Account menu', nm0, k && k.key === 'live' ? 'warn' : '', 'Opens the menu of the account: what kind of account it is and where it is saved, settings and shortcuts, export and import, one-click trading, Teach me and the guide of the page that is open.',
      { value: esc(nm0), vlabel: 'Account', sub: esc(st), secs: [sec('What kind of account', p(esc(g(() => k.title) || '')))], use: 'Check the account type here whenever you are not sure whether money is real.' }); });
  add('#userDot', () => C('Sync status', 'the state of the signed-in account', '', 'A dot on the avatar: green when the account is saved on the server, amber while it is saving, red when saving failed. It shows only on a signed-in account.', { use: 'A red dot means changes may not be saved: export the account.' }), { empty: true });

  /* ------------------------------------------------------------------ Hints switch and Guide button */
  add('#tipsOn', () => { const o = !document.body.classList.contains('no-hints'); return C('Hints', o ? 'explanations are on' : 'explanations are off', '', `Turns the explanations on or off for the whole app. It is <b>${on(o)}</b>: ${o ? 'the pointer turns into a yellow ? over a figure with an explanation and a click opens it; buttons show their card when you point at them.' : 'figures behave as before, with no ? and no card.'}`,
    { sec: null, secs: [sec('The two states', T([{ c: ['? on yellow', 'on: explanations available'], on: o }, { c: ['? on dark', 'off: plain interface'], on: !o }]))], use: 'Leave it on while you learn what a figure means, then turn it off for a quieter screen.' }); });
  add('#guideBtn, .mtool-guide', el => { const n = (el.getAttribute('aria-label') || lbl(el)).replace(/^Guide:\s*/, ''); return C(`Guide: ${n}`, 'the written guide of this page', '', `Opens the written guide of <b>${esc(n)}</b> in a new tab: how to read each number, how it is calculated and how to use it. It is the long version of the cards.`, { use: 'Read it once per page; the cards are for the moment, the guide is for understanding.' }); });

  /* ------------------------------------------------------------------ the status bar (shown on narrow screens) */
  add('#sbSess', el => C('Sessions', lbl(el) || 'no session', '', 'The trading sessions open now (Sydney, Tokyo, London, New York), from the clock of the market. Volume and spreads differ with the session; London and New York together are the busiest hours.', { value: esc(lbl(el) || '—'), vlabel: 'Open now', use: 'Trade the sessions your plan was built for.' }));
  add('#simClock', el => C('Market time', 'UTC clock of the market', '', `The time the market runs on, in UTC. Sessions, economic releases and the daily rollover are all timed against it.${/real/i.test(el.title) ? ' With live prices it is real time.' : ''}`, { value: esc(lbl(el).replace(' UTC', '')), vlabel: 'UTC now', use: 'Convert your own time zone to UTC once and keep it in mind.' }));
  add('#speedSel', () => { const v = g(() => document.getElementById('speedSel').value); return C('Market speed', `${v}× now`, '', 'Compresses market time to test strategies faster. It works only when no live prices reach the terminal: with live prices the market runs in real time and the control is hidden.', { value: `${v}×`, vlabel: 'Speed', use: 'Use Market replay to practise on past days.' }); });
  add('#sbLayout > span, #layoutSel', () => C('Workspace layout', 'where the panels sit', '', 'The layout of the Trade screen: which panels show and how big they are. Presets are Standard, Scalping, Analysis and Chart focus; drag panel edges to resize.', { use: 'Pick one layout per task and keep it; moving panels around costs attention.' }));
  add('#wsTabs button, #wsTabsCur', el => C(lbl(el) || 'Layout', 'a preset of the Trade screen', '', 'A saved arrangement of the Trade screen. A click applies it; your own resizing is kept per preset.', { use: 'Chart focus for reading, Scalping for execution.' }));

  /* ------------------------------------------------------------------ the account menu */
  const MENU = {
    helpBtn: el => /^Help/.test(lbl(el)) ? C('Help & shortcuts', 'opens the quick guide', '', 'Opens the quick guide with the keyboard shortcuts, what the app offers and the settings. The question mark key does the same.', { use: 'The fast way to the shortcut list.' })
      : C('Settings & shortcuts', 'opens the settings and the quick guide', '', 'Opens one page with the settings of the app (one-click trading, jurisdiction cap, execution costs, display) and the list of keyboard shortcuts.', { use: 'Set the jurisdiction and the execution costs once, before you trade.' }),
    exportBtn: () => { const n = nOpen(), h = g(() => S.history.filter(x => !x.nbp).length) || 0; return C('Export account', 'downloads a copy you keep', '', `Downloads the account as a JSON file named <b>tradeberry-account-YYYY-MM-DD.json</b>: ${n} open position${n === 1 ? '' : 's'}, ${h} closed trades, orders, alerts and settings.${live() ? ' On a server account it is a copy of the account as this page shows it.' : ''}`, { secs: [sec('Why', p('Browser storage can be cleared. A file is the one copy that does not depend on this browser.'))], use: 'Export before you reset, clear browser data or move to another device.' }); },
    importBtn: el => live() ? C(lbl(el) || 'Import preferences', 'brings back settings, not the account', '', 'On a server account an import brings back only the interface preferences: settings, ticket, watchlist, drawings and lines. The balance, positions, orders and history stay as the server keeps them.', { use: 'Use it to move your layout to another browser.' })
      : C(lbl(el) || 'Import account', 'replaces this account with a file', 'warn', 'Loads an exported file in place of the account in this browser. The file is checked and cleaned first; invalid records are skipped and counted. What is here now is replaced.', { watch: 'It replaces the account in this browser. Export first if you want to keep what is here.', use: 'Use it to restore a backup or to move to another browser.' }),
    resetAcct: () => C('Reset demo account', 'starts again from $100,000', 'warn', `Wipes the account and starts a fresh <b>${usd(g(() => INIT_BAL) || 100000)}</b> demo account${live() ? '' : '; saved layouts and settings on this device are reset too'}. It asks for confirmation first. Only a demo account has it.`, { watch: 'It cannot be undone: the history is gone with it. Export first.', use: 'Reset when you want a clean start for a new method, not to erase a bad week.' }),
    adminBtn: () => C('Administration', 'for the administrator of the server', '', 'Opens the administration: users and their modules, and the price data (the recorder, the archive and its gaps). It shows only to an administrator.', { use: 'Everything here acts on the server, for all users.' }),
    signOutBtn: () => C('Sign out', 'leaves the account on the server', '', 'Ends the session on this device. The account stays on the server with its positions and orders, and signs back in on any device. A local account in this browser is not affected.', { watch: 'Open positions stay open on the server while you are signed out.', use: 'Sign out on a shared computer.' })
  };
  add('#userPop [role^=menuitem]', el => {
    if (el.hasAttribute('data-oc')) { const o = g(() => !!S.set.oneClick); return C('One-click trading', o ? 'on: orders go out at once' : 'off: buttons only fill the ticket', o ? 'warn' : '', 'On: the chart Buy and Sell buttons, Shift+B and Shift+S, and a click on a Depth level send an order <b>immediately</b>. Off: they only fill in the order ticket, and you send from there.', { value: o ? 'On' : 'Off', vlabel: 'One-click trading', watch: o ? 'With it on a mis-click is an order. Keep the size small.' : '', use: 'Keep it off until your sizing is automatic.' }); }
    if (el.hasAttribute('data-teach')) return C('Teach me', 'a guided walk through this page', '', 'A guided tour of the page that is open: what each part shows, how to read it and how to use it, one step at a time. It does not change anything.', { use: 'Run it on a page you have not used yet.' });
    if (el.hasAttribute('data-guide')) { const n = lbl(el).replace(/^Guide:\s*/, ''); return C(`Guide: ${n}`, 'the written guide of this page', '', `Opens the written guide of <b>${esc(n)}</b> in a new tab. On the Trade dock the guide opens from here.`, { use: 'Read it once per page.' }); }
    if (el.classList.contains('user-out')) return MENU.signOutBtn();
    const f = MENU[el.dataset.u]; return f ? f(el) : null;
  });
  add('#userKind', el => { const k = kind(); return C('Account type', k ? k.key === 'live' ? 'real money' : 'no money at risk' : 'unknown', k && k.key === 'live' ? 'warn' : '', esc(g(() => k.title) || lbl(el)), { value: esc(lbl(el)), vlabel: 'Account', use: 'This line is the one to read when you wonder whether a click costs real money.' }); });
  add('#userName', el => C(lbl(el) || 'Account name', 'who the account belongs to', '', `The name of the account. ${/^Local/.test(lbl(el)) ? 'Not signed in: the account lives in this browser only.' : 'Signed in: the account is on the server and follows you to any device.'}`, { use: 'Sign in to keep the account across devices.' }));
  add('#userSt', el => C(lbl(el) || 'Save status', 'where and how it is saved', /unsaved|Saving|bad/i.test(lbl(el)) ? 'warn' : '', esc(g(() => document.getElementById('persistNote').textContent) || 'How this browser saves the account.'), { value: esc(lbl(el)), vlabel: 'Save status', use: 'Anything but a saved state means export a copy.' }));
  add('#userNote', el => C('Where the account lives', 'what the note says', '', esc(lbl(el)), { secs: [sec('Why you care', p('A browser can lose its storage. An exported file, or a signed-in account on the server, does not depend on it.'))], use: 'Export now and then.' }));

  /* ------------------------------------------------------------------ the sonification popup */
  const SCFG = () => g(() => sonCfg()) || { ticks: true, heart: true, vol: .5, sens: 1 };
  add('#sonPop > b', () => C('Listen to the market', 'the settings of the market sound', '', 'The two sounds the ear button plays and how loud and how sensitive they are. They are based on Janata and Childs (2004): a rising two-note chime is an uptick, a falling one a downtick.', { use: 'Set them once; the ear button switches the sound on and off.' }), { control: false });
  const SONC = {}; SONC.sonTicks = el => { const c = SCFG(), sym = g(() => S.set.sym) || 'EURUSD', st = .6 / c.sens, w = g(() => unitWord(sym)) || 'pips'; return C('Price ticks', c.ticks ? 'ticks are on' : 'ticks are off', '', `A two-note chime each time the active pair, <b>${esc(pretty(sym))}</b>, moves by one step: up for an uptick, down for a downtick. The step now is <b>${st.toFixed(2)} ${w}</b>; a move over four steps adds a third note. The register follows the distance from the price 24 hours ago.`, { value: c.ticks ? 'On' : 'Off', vlabel: 'Price ticks', use: 'Keep it on for the pair you trade; it follows the pair that is on the chart.' }); };
  SONC.sonHeart = el => { const c = SCFG(), n = nOpen(); return C('Portfolio heartbeat', c.heart ? 'the heartbeat is on' : 'the heartbeat is off', '', `A low two-note pulse every <b>1.6 s</b> while you hold positions. The pitch follows the open P&L against the equity; the pulse turns tense and doubles its tempo when a position is within a quarter of its stop distance from the stop.${n ? '' : ' It is silent now: nothing is open.'}`, { value: c.heart ? 'On' : 'Off', vlabel: 'Heartbeat', sub: `${n} open position${n === 1 ? '' : 's'}`, use: 'It works as an alarm for the stop: a tense pulse means a position is close to its stop.' }); };
  SONC.sonVol = el => { const v = +el.value; return C('Volume', `${Math.round(v * 100)}% of the sound level`, '', 'How loud the market sound is, from 0 to 100%. It scales both the ticks and the heartbeat and does not touch the alert beeps.', { value: Math.round(v * 100) + '%', vlabel: 'Volume', use: 'Low enough to work under, high enough to notice a change.' }); };
  SONC.sonSens = el => { const v = +el.value, sym = g(() => S.set.sym) || 'EURUSD', w = g(() => unitWord(sym)) || 'pips'; return C('Sensitivity', `a tick every ${(.6 / v).toFixed(2)} ${w}`, '', `How small a move makes a sound. A tick plays for each step of <b>0.6 ÷ sensitivity</b> ${w} on the active pair. A higher value means more sounds.`, { value: v.toFixed(2) + '×', vlabel: 'Sensitivity', sub: `${(.6 / v).toFixed(2)} ${w} per tick on ${esc(pretty(sym))}`, secs: [sec('Range', scale([{ w: 1, label: 'rare', tone: 'mid' }, { w: 1, label: 'normal', tone: 'ok' }, { w: 1, label: 'busy', tone: 'warn' }], .25, 3, v, x => x.toFixed(2) + '×'))], use: 'On a fast pair lower it; on a quiet one raise it.' }); };
  addE('#sonPop input', el => SONC[el.id] ? SONC[el.id](el) : null);
  add('#sonPop label', el => { const i = el.querySelector('input'); return i && SONC[i.id] ? VAR(SONC[i.id](i), 'its label') : null; }, { control: true });
  add('#sonPop small', () => C('Where the sounds come from', 'a published design', '', 'The design follows Janata and Childs (2004) on sonifying market data: a rising two-note chime means an uptick, a falling one a downtick, and the register follows the distance from the daily open. Here the reference is the price 24 hours ago.', { use: 'Listen for a day before you judge whether it helps you.' }));

  /* ------------------------------------------------------------------ the replay launcher */
  const RPD = '#rpDlg';
  add(`${RPD} h2`, () => C('Market replay', 'a replay of a market you can rewind', '', 'The launcher of Market replay. It rebuilds a market and plays it forward at your pace; what lies ahead is not computed or shown until you reach it. The replay has its own account, so your main account is not touched.', { use: 'Choose the source, set the start, press Start replay.' }));
  add(`${RPD} .modal > p:not(.muted):not([id])`, () => C('What a replay does', 'a market that does not show its future', '', 'Replay rebuilds the market and plays it forward at your pace. Nothing beyond the point you reached is computed, so you see only what a trader saw at that moment. Stepping back rebuilds the market from a saved checkpoint, so what you see is always computed forward from the past.', { use: 'Practise a setup on days you did not trade, then compare with how you trade it live.' }));
  add(`${RPD} #rpFrom`, () => C('Opened from a link', 'a shared replay', '', 'This launcher was opened from a replay link. The seed, the start and the exchange rates come from the link; nothing starts until you press Start replay.', { use: 'Check the start, then press Start replay.' }));
  add(`${RPD} #rpVer`, el => C('Different engine version', 'the same seed gives another market', 'warn', esc(lbl(el)), { watch: 'Results are not comparable with whoever made the link.', use: 'Ask for a link from the same version if you need the same market.' }));
  add(`${RPD} .mini-seg button[data-src]`, el => { const sim = el.dataset.src === 'sim', o = el.classList.contains('on');
    return sim ? C('Seed replay', o ? 'chosen' : 'choose this source', '', 'A generated market built from a <b>seed</b> (a whole number) and a start time. The same seed and the same start always give the same prices, so a replay can be shared and repeated. The rates it starts from are the platform’s G8 levels of a snapshot date.', { secs: [sec('What it covers', T([['Pairs', '16 G8 pairs'], ['Length', 'up to 3 days of market time'], ['Account', '$100,000, separate']]))], use: 'Use it to rehearse a setup on many different days.' })
      : C('Your session (1m bars)', o ? 'chosen' : 'choose this source', '', 'Replays the prices this session recorded, as 1-minute bars. The movement inside each minute is reconstructed: open, low, high, close on up bars; open, high, low, close on down bars.', { watch: 'It needs recorded 1-minute bars: at least 300 of them, otherwise the launcher says there are not enough yet.', use: 'Use it to replay the day you just traded, without the knowledge of how it ended.' }); });
  add(`${RPD} #rpSim label > span.muted, ${RPD} #rpBars label > span.muted`, el => { const t = lbl(el);
    if (/^Seed/.test(t)) return C('Seed', 'the number that fixes the market', '', 'A whole number from 0 to 4294967295. The seed decides every price of the replay: the same seed and start give the same market every time.', { use: 'Keep the seed of a replay you want to repeat or to share.' });
    if (/date/i.test(t)) return C('Start date (UTC)', 'the day the replay starts', '', 'The day the replay starts, in UTC. The start must be between the year 2000 and 2100; the replay then runs up to 3 days of market time.', { use: 'Pick the day, then set the time at the opening of the session you want to practise.' });
    if (/time/i.test(t)) return C('Start time (UTC)', 'the minute the replay starts', '', 'The minute the replay starts, in UTC; seconds are dropped to a whole minute. The market runs forward from here.', { use: 'Start at the opening of a session: London opens at 07:00 UTC and New York at 12:00 UTC on the clock of the app.' });
    return C('Start', 'where the recorded bars begin', '', 'Where in your recorded session the replay starts.', { use: 'Pick an hour before the move you want to practise.' }); }, { control: true });
  addE(`${RPD} #rpSeed`, el => { const v = el.value.trim(), ok = /^\d{1,10}$/.test(v) && +v <= 4294967295; return C('Seed', ok ? 'a valid seed' : 'not a valid seed', ok ? '' : 'bad', 'A whole number from 0 to 4294967295. It decides every price of the replay: the same seed and start always give the same market.', { value: esc(v || '—'), vlabel: 'Seed', watch: ok ? '' : 'Only digits, from 0 to 4294967295. The launcher refuses anything else.', use: 'Press Random for a new market; keep the number if you want to come back to this one.' }); });
  add(`${RPD} #rpRand`, () => C('Random seed', 'draws a new market', '', 'Puts a random whole number in the seed field, from 0 to 4294967295. Nothing starts until you press Start replay.', { use: 'Press it for a market you have never seen.' }));
  addE(`${RPD} #rpDate`, el => C('Start date (UTC)', 'the day the replay starts', '', 'The day the replay starts, in UTC. Typing a date clears the quick start.', { value: esc(el.value || '—'), vlabel: 'Date', use: 'Pick a day, then a start time at the opening of the session you want to practise.' }));
  addE(`${RPD} #rpTime`, el => C('Start time (UTC)', 'the minute the replay starts', '', 'The minute the replay starts, in UTC. Typing a time clears the quick start.', { value: esc(el.value || '—'), vlabel: 'Time', use: 'Start at a session opening: that is where the moves are.' }));
  add(`${RPD} #rpAgo button`, el => { const h = +el.dataset.ago; return C(`${h} h ago`, 'sets the start to now minus ' + h + ' hours', '', `Fills the date and time with the market clock of now minus <b>${h} hours</b>, so the replay starts ${h} hours back. You can still change the seed.`, { use: 'The quick way to replay the day you just traded.' }); });
  add(`${RPD} #rpRates`, el => C('Starting rates', 'where the prices begin', '', esc(lbl(el)) + ' The seven rates are what the generated prices are anchored to; they are the same for the same snapshot.', { use: 'A link carries its own rates, so a shared replay starts where the sender’s did.' }));
  add(`${RPD} #rpBarsStart`, el => C('Start', 'a point in your recorded session', '', `Where the replay starts inside your own recorded prices: 6 hours, 12 hours, 24 hours or 3 days before now. Now: <b>${esc(el.options[el.selectedIndex] ? el.options[el.selectedIndex].text : '')}</b>.`, { use: 'Start before the move you want to practise.' }));
  add(`${RPD} #rpBars > span.muted`, () => C('Your own prices', 'what this source replays', '', 'The 1-minute bars recorded in this session, replayed in order. Movement inside each minute is reconstructed, so ticks are not the real ones.', { watch: 'The bar still forming is never included.', use: 'Replay a session you traded to see it without hindsight.' }));
  add(`${RPD} .modal > div > p.muted`, () => C('Rules of a replay', 'what stays the same', '', 'The same seed and start give the same market every time. The replay account starts at $100,000 and is separate; your main account is frozen while Replay is open. A replay lasts up to 3 days of market time.', { secs: [sec('In numbers', T([['Replay account', '$100,000'], ['Longest replay', '3 days of market time'], ['Main account', 'frozen, untouched'], ['Speeds', '1×, 10×, 60×, 300×, 1800×']]))], use: 'Treat a replay like a live day: set your stop before you click.' }));
  add(`${RPD} #rpErr`, el => C('Why it did not start', 'the launcher refused', 'bad', esc(lbl(el)), { use: 'Fix the field it names and press again.' }));
  add(`${RPD} [data-x]`, () => C('Close', 'closes the launcher', '', 'Closes this dialog. Nothing is started and nothing is changed.', { use: 'Esc does the same.' }));
  add(`${RPD} [data-x2]`, () => C('Cancel', 'closes the launcher', '', 'Closes the launcher without starting a replay. The seed and the start you typed are not kept.', { use: 'Esc does the same.' }));
  add(`${RPD} #rpCopy`, () => C('Copy link', 'a link to this exact market', '', 'Copies a link with the seed, the start, the seven rates and the engine version. Whoever opens it gets this launcher filled in and, after Start replay, the same market.', { watch: 'The link needs the same engine version to give the same market.', use: 'Send it with a note about what to practise.' }));
  add(`${RPD} #rpGo`, el => C('Start replay', 'starts the replay in a layer over the app', '', `Starts the replay from the source and the start above. It opens over the app with its own account of <b>${usd(g(() => INIT_BAL) || 100000)}</b> and a transport bar; your main account is frozen until you close it.`, { watch: 'The seed or the date is checked first; an invalid one shows the reason and nothing starts.', use: 'Close the replay with the Close replay control; the main account comes back unchanged.' }));

  /* ------------------------------------------------------------------ Help: keys and features */
  const KEYS = [
    [/Command bar/, '⌘ or Ctrl + K: Command bar', 'Opens the command bar from anywhere. Press it again to close.', 'Orders run on a second Enter; read the line before you confirm.'],
    [/^ShiftB/, 'Shift + B: Buy', 'Fills the ticket for a buy of the pair on the chart. With one-click trading on it sends the order immediately.', 'Leave one-click off until your size is automatic.'],
    [/^ShiftS/, 'Shift + S: Sell', 'Fills the ticket for a sell of the pair on the chart. With one-click trading on it sends the order immediately.', 'Leave one-click off until your size is automatic.'],
    [/Timeframes/, '1 to 5: Timeframes', 'Changes the chart timeframe: 1 is 1 minute, 2 is 5 minutes, 3 is 15 minutes, 4 is 1 hour, 5 is 4 hours.', 'Look at two timeframes before a trade: the one you trade on and the one above it.'],
    [/Workspaces/, 'Alt + 1 to 5: Workspaces', 'Jumps to a workspace: 1 Trade, 2 Monitor, 3 Research, 4 Strategy Lab, 5 Coach.', 'Use it to flip to Research and back without the mouse.'],
    [/Next \/ previous pair/, 'Up and Down: next or previous pair', 'On the Trade screen, moves to the next or previous pair of the 16 pairs and loads it in the chart, the ticket and the brief.', 'Step through the pairs quickly to find the one that moves.'],
    [/Close all/, 'Shift + X: Close all', 'Closes every open position at the market. The first time it asks for confirmation; after that it closes everything on one press.', 'It books the floating P&L and fills can slip. Use it deliberately.'],
    [/Measure tool/, 'M: Measure tool', 'Switches the measure tool on the chart: click a start point, then an end point, and the box between them shows how far price moved. Esc cancels.', 'Measure the stop and the target before you place them.'],
    [/Market brief/, 'I: Market brief', 'Opens the Market Brief of the pair on the chart.', 'Read the key levels before you place a stop.'],
    [/Backtester/, 'T: Backtester', 'Opens the Backtester in the Strategy Lab.', 'Test a rule before you trade it.'],
    [/Trendline/, 'L and F: Trendline and Fibonacci', 'Selects a drawing tool: L for a trendline, F for Fibonacci retracements and extensions. Drawings are anchored in time and survive a change of timeframe.', 'Draw on the higher timeframe; the lines carry over.'],
    [/Delete selected drawing/, 'Del: Delete selected drawing', 'Deletes the drawing that is selected on the chart. It does not touch positions or orders.', 'Click a line to select it first.'],
    [/Cycle chart layouts/, 'G: Cycle chart layouts', 'Cycles the chart layouts: one chart, two side by side, two stacked, three, four. Shift+G goes back.', 'Use two charts to watch the trade timeframe and the one above it.'],
    [/Observatory/, 'O: Observatory', 'Opens the Observatory: correlation, regimes, recurrence, drivers and the rest of the research tools.', 'Check correlation before adding a second trade.'],
    [/Behaviour/, 'Y: Behaviour', 'Opens the Behaviour pages in the Coach: pre-mortem, skipped trades and the disposition effect.', 'Open it after a losing day.'],
    [/Full screen/, 'Shift + F: Full screen', 'Switches full screen on or off.', 'Same as the full screen button in the header.'],
    [/Cancel tool/, 'Esc: Cancel tool / close', 'Cancels the tool you are using (measure, drawing), closes the command bar and this guide.', 'The way out when a tool is stuck.']
  ];
  add('#help ul.keys li', el => { const t = lbl(el), k = KEYS.find(x => x[0].test(t)); if (!k) return null; const kb = k[1].split(':')[0];
    return C(k[1].replace(/^[^:]*:\s*/, ''), 'a keyboard shortcut', /Close all/.test(k[1]) ? 'warn' : '', k[2], { value: esc(kb), vlabel: 'Keys', use: k[3], watch: /Buy|Sell/.test(k[1]) ? 'It sends only when one-click trading is on; otherwise it just fills the ticket.' : /Close all/.test(k[1]) ? 'There is no undo.' : '' }); });
  const FEAT = [
    [/^Risk-first ticket/, 'Risk-first ticket', 'The ticket sizes by percent of equity, risk in dollars or lots, and shows the dollar risk, the reward to risk and the margin before you click. The size follows the stop, not the other way round.', 'Decide the stop first; let the size follow.'],
    [/^Drag SL\/TP/, 'Drag the stop and the target', 'Drag the stop loss and take profit lines on the chart, for the ticket and for open positions. The risk and the ratio update as you drag.', 'Move a stop only toward the entry, never away.'],
    [/^Correlation guard/, 'Correlation guard', 'Warns when a new trade stacks exposure you already hold, such as a second long on a pair that moves with the first.', 'Two correlated trades are one trade with double the size.'],
    [/^Net currency exposure/, 'Net currency exposure', 'Splits each position into its currencies and adds them up, so you see that long EURUSD and short USDCHF may both be short the dollar.', 'Check the net before adding a trade.'],
    [/^Natural-language command bar/, 'Command bar', 'One line for execution, alerts and navigation. Orders run on a second Enter.', 'Press Ctrl or ⌘ K.'],
    [/^Risk Lab/, 'Risk Lab', 'Resamples your journal into 1,000 Monte Carlo paths to show the range of outcomes your own stats allow, including the drawdown you should expect.', 'It needs a journal of enough trades to say anything.'],
    [/^Time compression/, 'Time compression', 'Speeds the market clock to rehearse a session in minutes. It works only when no live prices reach the terminal, and in Market replay (1×, 10×, 60×, 300×, 1800×); with live prices the market runs in real time and the speed control is hidden.', 'Use Market replay to rehearse.'],
    [/^Multi-chart layouts/, 'Multi-chart layouts', 'Up to 2 × 2 charts with a synced crosshair, timeframe link, one-click trading in every pane (when one-click is on) and auto-fill with correlated pairs.', 'Press G to cycle the layouts.'],
    [/^Drawing tools/, 'Drawing tools', 'Trendlines, rays, channels and Fibonacci retracements and extensions. They are anchored in time, so they survive a timeframe change, and a trendline can fire an alert.', 'Draw on the higher timeframe first.'],
    [/^Strategy backtester/, 'Strategy backtester', 'Tests a rule on the platform’s own prices, fetched when you run it, with minute-level fills, an out-of-sample check, a parameter heatmap and a robustness test across all pairs.', 'A rule that works only in-sample is not a result.'],
    [/^Market Brief/, 'Market Brief', 'An analyst-style write-up for every pair: the trend score, key levels, the timeframes, the next event and a plan template you can load in the ticket.', 'Press I to open it.'],
    [/^Observatory/, 'Observatory', 'Research tools on all pairs: the correlation constellation, regime map (Hurst against entropy), intrinsic-time events, historical analogues with a hit-rate check, recurrence plot, currency drivers, volatility clock and a tapestry of all pairs.', 'Press O to open it.'],
    [/^Behaviour/, 'Behaviour', 'A pre-mortem before risky trades with red flags found automatically, tracking of trades you skipped, and a disposition-effect meter (Odean’s PGR against PLR).', 'Press Y to open it.'],
    [/^Baskets/, 'Baskets', 'Build a weighted currency index, chart it, find its closest pair and trade it as one set of legs. Intrinsic-time candles draw one candle per move of a set size.', 'Use a basket to trade a currency, not a pair.'],
    [/^Listen to the market/, 'Listen to the market', 'Sonified ticks and a portfolio heartbeat. The ticket also shows the random-walk odds that the target is hit before the stop and the typical time to resolve.', 'The odds assume a driftless walk: they are a baseline, not a forecast.'],
    [/^Depth-of-market/, 'Depth-of-market ladder', 'A ladder of prices around the market: one click places a limit or stop order at that exact price (an order is sent at once only with one-click trading on).', 'Click the price, not the side: the side follows the price.'],
    [/^Trade coach/, 'Trade coach', 'Reads your closed trades and flags revenge trades, loss aversion and your best pairs and sessions.', 'It needs at least ten trades before it says anything.']
  ];
  add('#help ul.feat li', el => { const t = lbl(el), f = FEAT.find(x => x[0].test(t)); if (!f) return null; return C(f[1], 'what the app offers', '', f[2], { secs: [sec('The line in this guide', p(esc(t)))], use: f[3] }); });
  add('#help .help-grid h3', el => { const t = lbl(el); return /keyboard/i.test(t) ? C('Keyboard', 'the shortcuts of the app', '', 'Every shortcut works anywhere on the screen except while you type in a field. Point at a line for what the key does.', { use: 'Learn Alt+1 to 5, Shift+B and S, and the digits for timeframes first.' })
    : C('What makes it different', 'the features that set the app apart', '', 'The features this app has beyond a chart and a ticket: sizing from risk, correlation and exposure checks, the research tools and the coach. Point at a line for what it does and where to find it.', { use: 'Read it once; the Teach me tour shows where each one lives.' }); });
  add('#help > .modal > .ph h2', () => C('Quick guide', 'shortcuts, features, settings', '', 'The quick guide: the keyboard shortcuts, what the app offers, where prices come from and where the account is kept, then the settings and the account actions. The written guide of each page is separate.', { use: 'Open it with the question mark key, from anywhere.' }));
  add('#help [data-close]', () => C('Close', 'closes the guide', '', 'Closes this dialog. Settings take effect when you change them, so there is nothing to confirm.', { use: 'Esc does the same.' }));
  add('#help .help-tour > button', () => C('Start the 60-second tour', 'a quick walk through the app', '', 'Starts a short guided tour: markets, chart, ticket, tools and layouts, a step at a time. It only highlights and explains; it changes nothing.', { use: 'Run it once on a new account; use Teach me in the account menu for the page you are on.' }));
  add('#help .help-tour > span', () => C('The tour', 'what it covers', '', 'The tour walks through markets, chart, ticket, tools and layouts in about a minute. Use the button on its left to start it.', { use: 'You can leave the tour at any step.' }));

  /* ------------------------------------------------------------------ Help: sources and notes */
  add('#simLabel', el => { const l = lbl(document.getElementById('simLabel')), liveP = /^LIVE/.test(l), k = kind(); return C('Price source', liveP ? 'real prices from the broker platform' : 'no live prices', liveP ? 'ok' : 'warn',
    liveP ? 'The prices are the broker platform’s real bid and ask. Orders on a server account are executed there on these prices.' : 'No live prices from the broker platform reach the terminal right now. What you see is not the market.', { value: esc(l.split(' ')[0]), vlabel: 'Source', sub: esc(g(() => k.label) || ''), use: 'Check it before you trade: the header pill says the same.' }); });
  add('#simLabel > b', el => { const w = lbl(el); return C(w, w === 'LIVE' ? 'real prices' : 'no live prices', w === 'LIVE' ? 'ok' : 'warn', w === 'LIVE' ? 'The word that says the prices on screen are the broker platform\u2019s own bid and ask.' : 'The word that says no live prices reach this terminal: what you see is not the platform\u2019s market.', { use: 'The same word, as a pill, sits in the header.' }); });
  add('#persistNote', el => { const t = lbl(el); return C('Where it is saved', /Session only|only in this tab/.test(t) ? 'not kept after you close the tab' : /server/.test(t) ? 'on the server' : 'in this browser', /Session only|only in this tab|not saved/.test(t) ? 'warn' : '', esc(t), { use: 'Export is the copy you keep yourself.' }); });
  const KB = { 'Shift': 'The Shift key, held with the letter next to it.', 'Alt': 'The Alt key (Option on a Mac), held with a digit to jump to a workspace.', '⌘/Ctrl': 'Command on a Mac, Control on Windows and Linux.', 'Esc': 'The Escape key: cancels the tool in use and closes the command bar and this guide.', 'Del': 'The Delete key: removes the drawing that is selected on the chart.' };
  const kbdCard = el => { const t = lbl(el), li = el.closest('li, small'), row = li ? lbl(li) : ''; return C(`Key: ${t}`, 'a key of the shortcut', '', (KB[t] || `The ${esc(t)} key.`) + ` Part of the shortcut: ${esc(row)}.`, { use: 'The full list is in the Keyboard column.' }); };
  add('#help .set-row kbd', kbdCard, { control: true });
  add('#help kbd', kbdCard);
  add('#help p.muted.small:not(#chartLicence):not(#buildTag)', el => {
    if (el.querySelector('#persistNote')) return C('Where your account is kept', 'what this browser does', '', esc(txt(el, '#persistNote') || lbl(el)), { secs: [sec('Why you care', p('Browser storage can be cleared or lost. Export is the only copy that does not depend on it.'))], use: 'Export after a session you do not want to lose.' });
    return C('About the prices', 'what the note describes', '', 'The note describes the generated market used when no live prices reach the terminal and in Market replay: volatility follows the trading sessions and the currencies move together through shared factors. With live prices the platform’s own prices apply instead.', { watch: 'It is not a statement about live prices.', use: 'Read the Price source line above to know which market you are looking at.' });
  });
  add('#helpMoney', el => { const k = kind(); return C('Money at risk', k && k.key === 'live' ? 'real money' : 'no real money', k && k.key === 'live' ? 'warn' : '', esc(g(() => k.label) || lbl(el)), { use: 'This sentence changes with the account type: read it when you are not sure.' }); });
  add('#chartLicence', () => C('Chart licence', 'the library that draws the charts', '', 'The charts are drawn by TradingView Lightweight Charts, version 5.2.1, under the Apache License 2.0. The notice is required by the licence.', { use: 'Nothing to do; it is here because the licence asks for it.' }));
  add('#chartLicence a', () => C('TradingView', 'opens an external site', '', 'Opens the website of TradingView, the maker of the chart library, in a new tab. It leaves tradeBerry; your account is not affected.', { use: 'Only if you want to read about the library.' }));
  add('#help p.muted.small > b:first-child, #chartLicence > b', el => /^Charts/.test(lbl(el)) ? C('Charts', 'the library behind the charts', '', 'The charts are drawn with TradingView Lightweight Charts. The line after it carries the licence notice.', { use: 'Nothing to do.' }) : C('Where your account is kept', 'storage and backup', '', 'The paragraph says where this browser saves the account and what to do about it: browser storage can be cleared, an exported file cannot.', { use: 'Export after a session you want to keep.' }));
  add('#buildTag', el => { const m = lbl(el).match(/v([\d.]+).*build (\S+)/) || []; return C('Version and build', 'which code is running', '', 'The version of tradeBerry and the build id of the code your browser loaded. A new build reaches you with one refresh.', { value: esc(m[1] ? 'v' + m[1] : lbl(el)), vlabel: 'Version', sub: `build ${esc(m[2] || 'dev')}`, use: 'Quote it when you report a problem.' }); });

  /* ------------------------------------------------------------------ Help: settings */
  const JD = { none: 'no cap: every instrument at its sheet leverage', eu: 'ESMA: 1:30 on major pairs, 1:20 on other pairs, gold and major indices, 1:10 other commodities and minor indices, 1:5 stocks, 1:2 crypto', uk: 'ESMA caps; crypto derivatives are not offered to UK retail', au: 'ESMA caps (AU retail uses the ESMA index list)', us: 'NFA: 1:50 on major pairs, 1:20 on other pairs; no CFDs' };
  const setName = el => { const r = el.closest('.set-row'); if (!r) return ''; const i = r.querySelector('input,select'); return i ? i.id : ''; };
  const SETC = {
    oneClickSet: () => { const o = g(() => !!S.set.oneClick); return C('One-click trading', o ? 'on: orders go out at once' : 'off: buttons only fill the ticket', o ? 'warn' : '', 'Off: the quick-trade buttons, the B and S buttons on chart panes and Shift+B or Shift+S only fill in the order ticket, and you send from there. On: they send a market order immediately.', { value: o ? 'On' : 'Off', vlabel: 'One-click trading', watch: o ? 'A mis-click is an order. Keep the size small.' : '', use: 'Turn it on only when your size is fixed and you trust your hands.' }); },
    jurSel: el => { const j = g(() => jurOf(S.set)), k = el.value || 'none'; return C('Jurisdiction cap', k === 'none' ? 'no cap' : `${esc(g(() => JUR[k].opt) || k)} cap`, k === 'none' ? '' : 'warn', `An optional regulatory limit on leverage, on top of the instrument sheet. Now: <b>${esc(JD[k] || '')}</b>.${j && !j.none ? ' ' + esc(g(() => capText(j)) || '') : ''}`, { secs: [sec('The choices', T(Object.keys(JD).map(x => ({ c: [x === 'none' ? 'None' : x.toUpperCase(), JD[x]], on: x === k }))))], watch: 'A change recomputes the margin of open positions; with open trades it shows the new level first and asks.', use: 'Pick the jurisdiction that applies to you, or None to test with sheet leverage.' }); },
    tkSlipOn: el => { const c = g(() => execCfg()) || {}; return C('Slippage', el.checked ? 'slippage is on' : 'slippage is off', '', `When on, a market order fills at a price that can differ from the quote by a random amount: a normal distribution with the σ below, plus the price movement during the latency. A positive deviation is against you. When off, orders fill exactly at the quote.${live() ? ' On the server account this is set by the execution server and cannot be edited here.' : ''}`, { value: el.checked ? 'On' : 'Off', vlabel: 'Slippage', sub: `σ ${c.sd != null ? c.sd : '—'} pips · latency ${c.lat != null ? c.lat : '—'} ms`, use: 'Keep it on: a test without slippage is optimistic.' }); },
    tkSlipSd: el => C('Slippage σ', `${el.value || 0} pips`, '', 'The standard deviation of the random part of the fill, in pips. About two thirds of fills land within this distance of the quote; larger moves are rarer. Range 0 to 5.', { value: esc(el.value || '0'), vlabel: 'σ in pips', use: 'The default is 0.2 pip, a calm market; raise it to test a bad fill.', watch: live() ? 'Fixed by the execution server on this account.' : '' }),
    tkLat: el => C('Latency', `${el.value || 0} ms`, '', 'The delay between your click and the order reaching the market, in milliseconds. It is randomised between 0.5 and 1.5 times the value, and the price keeps moving during it, so a higher value widens the fill. Range 0 to 2000.', { value: esc(el.value || '0'), vlabel: 'Latency in ms', use: 'The default is 120 ms.', watch: live() ? 'Fixed by the execution server on this account.' : '' }),
    tkComm: el => C('Commission', `$${el.value || 0} per lot`, '', 'An extra commission in dollars per lot, for the round turn (open and close), added to the one the instrument sheet charges. It is part of the cost of every trade and of the backtests that use the account costs. Range 0 to 50.', { value: '$' + esc(el.value || '0'), vlabel: 'Per lot, round turn', use: 'Set it to what your broker charges; a strategy that only works at zero cost does not work.', watch: live() ? 'Fixed by the execution server on this account.' : '' }),
    paletteSet: el => C('Colour palette', el.options[el.selectedIndex].text, '', 'The two colours of rising and falling prices, profit and loss. The colour-blind safe palette uses blue and orange, which stay distinct in red-green colour blindness; signs and arrows show in both.', { value: esc(el.options[el.selectedIndex].text), vlabel: 'Palette', use: 'Combine it with hollow candles if colour alone is hard to read.' }),
    updnSet: el => C('Rising colour', el.options[el.selectedIndex].text, '', 'Which colour means up. Red rising is the convention in mainland China and Taiwan. Errors and warnings keep their own colours.', { value: esc(el.options[el.selectedIndex].text), vlabel: 'Rising colour', use: 'Choose the convention you read fastest.' }),
    candleSet: el => C('Candles', el.options[el.selectedIndex].text, '', 'Filled draws every candle as a solid body. Hollow draws a rising candle as an outline, so direction reads without colour.', { value: esc(el.options[el.selectedIndex].text), vlabel: 'Candles', use: 'Hollow is the one to choose if you rely on shape more than colour.' })
  };
  addE('#help .set-row input, #help .set-row select, #help #tkExecField input', el => { const f = SETC[el.id]; return f ? f(el) : null; });
  add('#help .set-row b, #help .set-row small, #help .set-row label', el => { const id = setName(el); const f = SETC[id]; const i = el.closest('.set-row').querySelector('input,select'); if (!f || !i) return null; const h = f(i); return el.tagName === 'SMALL' ? VAR(h, 'the note') + sec('The note beside the setting', p(esc(lbl(el)))) : el.tagName === 'LABEL' ? VAR(h, 'its label') : VAR(h, 'the setting'); }, { control: true });
  add('#help .help-set > h3', () => C('Settings', 'how the app behaves', '', 'The settings of the app: one-click trading, the jurisdiction cap, execution costs and the display. They apply as soon as you change them and are saved with your settings.', { use: 'Set them once, before the first trade.' }));
  add('#marginNote', () => { const a = acct(); return C('How margin works', 'the rules of margin in this app', '', 'Margin level is equity divided by used margin, times 100. Under 100% no new position can open; at 50% the broker closes positions (stop-out). Used margin is the initial margin of each position, fixed when it opens (notional at the fill ÷ leverage) and scaled when part of it is closed; it does not follow the price.', { value: a && isFinite(a.level) ? nf0.format(a.level) + '%' : '—', vlabel: 'Your margin level now', sub: a ? `used margin ${usd(a.mg)}` : '', use: 'Know the 100% and 50% lines before you size.' }); });
  add('#execH', () => C('Execution', 'how orders fill', '', 'The costs and frictions applied to every fill: slippage, latency and commission. Orders fill all or nothing. They make a result closer to what a real fill gives.', { use: 'Leave them on when you test a method.' }));
  add('#tkExecField .lbl-row > label, #tkExecField .lbl-row > span', el => C('Execution', (el.tagName === 'SPAN' ? 'its unit line · ' : 'its label · ') + 'all-or-nothing fills', '', 'Every order fills completely or not at all: there are no partial fills. The fields below set the slippage, the latency and the commission.', { use: 'Read the three fields as the cost of getting in and out.' }), { control: true });
  add('#tkExecField > div > span.small', el => C(lbl(el), 'the unit of the field beside it', '', /commission|lot/i.test(lbl(el)) ? 'The commission is in dollars per lot, for the round turn: opening and closing together.' : /ms/.test(lbl(el)) ? 'Milliseconds: the latency between the click and the market.' : 'Pips: the unit of the slippage deviation; the latency field follows.', { use: 'Read it with the number next to it.' }), { control: true });
  add('#tkExecField > div > label.small', el => { const i = el.control || el.querySelector('input'); const f = i && SETC[i.id]; return f ? VAR(f(i), 'its label') : null; }, { control: true });
  add('#dispH', () => C('Display', 'colours and candles', '', 'How prices are drawn: the palette, which colour is up and filled or hollow candles. They are preferences of this browser and survive a reset of the account.', { use: 'Change them if reading the chart costs effort.' }));
  add('#help .set-disp small, #help .set-disp .set-row > span', el => { const i = el.closest('.set-row').querySelector('select'); return i && SETC[i.id] ? VAR(SETC[i.id](i), 'the note') + sec('The note beside the setting', p(esc(lbl(el).slice(0, 160)))) : null; }, { control: true });
  add('#exportBtn', MENU.exportBtn);
  add('#importBtn', MENU.importBtn);
  add('#resetAcct', MENU.resetAcct);
})();
